    70	func TestLRU(t *testing.T) {
    71		evictCounter := 0
    72		onEvicted := func(k int, v int) {
    73			if k != v {
    74				t.Fatalf("Evict values not equal (%v!=%v)", k, v)
    75			}
    76			evictCounter++
    77		}
    78		l, err := NewWithEvict(128, onEvicted)
    79		if err != nil {
    80			t.Fatalf("err: %v", err)
    81		}
    82	
    83		for i := 0; i < 256; i++ {
    84			l.Add(i, i)
    85		}
    86		if l.Len() != 128 {
    87			t.Fatalf("bad len: %v", l.Len())
    88		}
    89		if l.Cap() != 128 {
    90			t.Fatalf("expect %d, but %d", 128, l.Cap())
    91		}
    92	
    93		if evictCounter != 128 {
    94			t.Fatalf("bad evict count: %v", evictCounter)
    95		}
    96	
    97		for i, k := range l.Keys() {
    98			if v, ok := l.Get(k); !ok || v != k || v != i+128 {
    99				t.Fatalf("bad key: %v", k)
   100			}
   101		}
   102		for i, v := range l.Values() {
   103			if v != i+128 {
   104				t.Fatalf("bad value: %v", v)
   105			}
   106		}
   107		for i := 0; i < 128; i++ {
   108			if _, ok := l.Get(i); ok {
   109				t.Fatalf("should be evicted")
   110			}
   111		}
   112		for i := 128; i < 256; i++ {
   113			if _, ok := l.Get(i); !ok {
   114				t.Fatalf("should not be evicted")
   115			}
   116		}
   117		for i := 128; i < 192; i++ {
   118			l.Remove(i)
   119			if _, ok := l.Get(i); ok {
   120				t.Fatalf("should be deleted")
   121			}
   122		}
   123	
   124		l.Get(192) // expect 192 to be last key in l.Keys()
   125	
   126		for i, k := range l.Keys() {
   127			if (i < 63 && k != i+193) || (i == 63 && k != 192) {
   128				t.Fatalf("out of order key: %v", k)
   129			}
   130		}
   131	
   132		l.Purge()
   133		if l.Len() != 0 {
   134			t.Fatalf("bad len: %v", l.Len())
   135		}
   136		if _, ok := l.Get(200); ok {
   137			t.Fatalf("should contain nothing")
   138		}
   139	}
   140	
   141	// test that Add returns true/false if an eviction occurred
   142	func TestLRUAdd(t *testing.T) {
   143		evictCounter := 0
   144		onEvicted := func(k int, v int) {
   145			evictCounter++
   146		}
   147	
   148		l, err := NewWithEvict(1, onEvicted)
   149		if err != nil {
   150			t.Fatalf("err: %v", err)
   151		}
   152	
   153		if l.Add(1, 1) == true || evictCounter != 0 {
   154			t.Errorf("should not have an eviction")
   155		}
   156		if l.Add(2, 2) == false || evictCounter != 1 {
   157			t.Errorf("should have an eviction")
   158		}
   159	}
   160	
